// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract LiquidStaking is ERC20, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable stakingToken;
    uint256 public stakingFee;

    mapping(address => uint256) public stakeBalances;

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);

    constructor(address _stakingToken, uint256 _stakingFee) ERC20("Staked Token", "stToken") {
        stakingToken = IERC20(_stakingToken);
        stakingFee = _stakingFee;
    }

    // Stake a certain amount of stakingToken
    function stake(uint256 amount) external nonReentrant {

        require(amount > 0, "Amount must be greater than zero");
        stakingToken.safeTransferFrom(msg.sender, address(this), amount);

        uint256 netAmount = amount - (amount * stakingFee / 10000);
        stakeBalances[msg.sender] += netAmount;
        _mint(msg.sender, netAmount);

        emit Staked(msg.sender, amount);
    }

    // Unstake a certain amount of staked tokens
    function unstake(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be greater than zero");

        require(stakeBalances[msg.sender] >= amount, "Insufficient stake balance");

        stakeBalances[msg.sender] -= amount;
        _burn(msg.sender, amount);

        uint256 withdrawalAmount = amount + (amount * stakingFee / 10000);
        stakingToken.safeTransfer(msg.sender, withdrawalAmount);

        emit Unstaked(msg.sender, amount);
    }

    // Fetch the total amount of staked tokens for a user
    function getStakeBalance(address user) external view returns (uint256) {
        return stakeBalances[user];
    }

    // Update the staking fee
    function updateStakingFee(uint256 newFee) external onlyOwner {
        stakingFee = newFee;
    }

    // Transfer function overridden to prevent direct transfer of staked tokens
    function transfer(address recipient, uint256 amount) public override returns (bool) {
        require(amount == 0, "Cannot transfer staked tokens directly");
        return super.transfer(recipient, amount);
    }

    // TransferFrom function overridden to prevent direct transfer of staked tokens
    function transferFrom(address sender, address recipient, uint256 amount) public override returns (bool) {
        require(amount == 0, "Cannot transfer staked tokens directly");
        return super.transferFrom(sender, recipient, amount);
    }
}
